use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let a = input[0].as_array().unwrap();
    let b = input[1].as_array().unwrap();
    let mut result = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < a.len() && j < b.len() {
        if a[i].as_i64().unwrap() < b[j].as_i64().unwrap() {
            result.push(a[i].as_i64().unwrap());
            i += 1;
        } else {
            result.push(b[j].as_i64().unwrap());
            j += 1;
        }
    }
    result.extend(a[i..].iter().cloned());
    result.extend(b[j..].iter().cloned());
    Value::Array(result)
}
